use vstd::prelude::*;

verus! {

fn splitlines(a: Vec<String>, keepends: bool) -> Vec<Vec<String>>
    ensures a.len() == result.len()
    ensures forall|i: usize| (i < result.len() ==> 
        result[i].len() > 0
    )
{
    let mut result: Vec<Vec<String>> = Vec::new();
    
    for i in 0..a.len()
        invariant
            result.len() == i,
            forall|j: usize| (j < result.len() ==> result[j].len() > 0)
    {
        let lines = split_string_into_lines(&a[i], keepends);
        result.push(lines);
    }
    
    result
}

fn split_string_into_lines(s: &String, keepends: bool) -> Vec<String>
    ensures result.len() > 0
{
    let mut lines: Vec<String> = Vec::new();
    let mut current_line = String::new();
    
    let chars: Vec<char> = s.chars().collect();
    
    for i in 0..chars.len() {
        let c = chars[i];
        
        if c == '\n' || c == '\r' {
            if keepends {
                current_line.push(c);
            }
            lines.push(current_line);
            current_line = String::new();
            
            // Handle \r\n as a single line ending
            if c == '\r' && i + 1 < chars.len() && chars[i + 1] == '\n' {
                if keepends {
                    current_line.push('\n');
                }
            }
        } else {
            current_line.push(c);
        }
    }
    
    // Add the last line if there's any remaining content or if the string was empty
    if current_line.len() > 0 || lines.len() == 0 {
        lines.push(current_line);
    }
    
    // Ensure we always return at least one element
    if lines.len() == 0 {
        lines.push(String::new());
    }
    
    lines
}

}